// Close rewards 
public(package) fun close_reward<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,
    reward_type: u8,
    reward_index: u64,
    clock: &Clock,
): Balance<RewardCoinType>{
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    pool_reward_manager.close_pool_reward<RewardCoinType>(reward_index, clock)
}


public(package) fun update_obligation_reward_manager<MarketType, CoinType>(
    self: &mut LiquidityMiner<MarketType>,
    reward_type: u8,
    obligation_id: ID,
    new_share: u64,
    clock: &Clock,
){
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);

    if (!pool_reward_manager.borrow_obligation_reward_managers().contains(obligation_id)){
        pool_reward_manager.new_obligation_reward_manager(obligation_id, clock);
    };

    pool_reward_manager.change_obligation_reward_manager_share(obligation_id, new_share, clock);
}

public(package) fun claim_rewards<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,

    reward_type: u8,
    obligation_id: ID,

    clock: &Clock,
    reward_index: u64,
): Balance<RewardCoinType>{
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    let claimed_reward = pool_reward_manager.claim_rewards(obligation_id, clock, reward_index);
    claimed_reward
}

fun get_reward_table_mut<MarketType>(self: &mut LiquidityMiner<MarketType>, reward_type: u8): &mut Table<TypeName, PoolRewardManager> {
    match (reward_type) {
        DepositRewardType => &mut self.deposit,
        BorrowRewardType => &mut self.borrow,
        // sanity check only
        _ => abort(0),
    }
}

fun get_reward_manager_mut<MarketType, CoinType>(self: &mut LiquidityMiner<MarketType>, reward_type: u8): &mut PoolRewardManager {
    let coin_type = type_name::with_defining_ids<CoinType>();

    let t = self.get_reward_table_mut<MarketType>(reward_type);
    assert!(t.contains(coin_type), error::liquidity_mining_pool_not_initialized());

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

